(()=>{
const QUESTION_COUNT=5,MAX_COMPANY=120,MAX_POSITION=120,MAX_JD=12000,MAX_ANSWER=6000;
const STORAGE_KEY="eit-mock-interview-v1",STORAGE_VERSION=1,MAX_HISTORY=5;
const labels={relevance_score:"相关性 Relevance",structure_score:"结构 Structure",evidence_score:"证据 Evidence",action_result_score:"行动与结果 Action & Result",clarity_score:"清晰度 Clarity",english_score:"英语表达 English"};
const freshSession=()=>({id:"",createdAt:"",screen:"setup",company:"",position:"",jd:"",questions:[],current:0,attempts:[],feedback:null,retrying:false,busy:false,error:"",draft:"",completed:false,summary:null});
const session=freshSession();
let helpers={navigate:()=>{},toast:()=>{}},store;
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const endpoint=()=>String(window.EIT_CONFIG?.mockInterviewEndpoint||"").trim();
const list=(items,cls="")=>`<ul class="${cls}">${(items||[]).map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`;
const scoreClass=n=>n>=4?"score-good":n>=3?"score-mid":"score-low";
const plainObject=value=>value&&typeof value==="object"&&!Array.isArray(value);
const safeText=(value,max=MAX_JD)=>typeof value==="string"?value.slice(0,max):"";

function cleanFeedback(value){
  if(!plainObject(value))return null;
  const keys=Object.keys(labels);
  if(keys.some(key=>!Number.isFinite(value[key])||value[key]<0||value[key]>5))return null;
  const clean={...value};
  [...keys,"total_score"].forEach(key=>clean[key]=Number(value[key])||0);
  ["strengths","improvement_advice","better_structure","retry_focus","improved","still_missing"].forEach(key=>clean[key]=Array.isArray(value[key])?value[key].filter(x=>typeof x==="string").slice(0,8):[]);
  clean.language_fixes=Array.isArray(value.language_fixes)?value.language_fixes.filter(plainObject).map(x=>({original:safeText(x.original,1000),improved:safeText(x.improved,1000),reason:safeText(x.reason,1000)})).slice(0,8):[];
  ["overall_diagnosis","biggest_weakness","suggested_answer","suggested_answer_rationale"].forEach(key=>clean[key]=safeText(value[key],6000));
  return clean;
}
function cleanRecord(value){
  if(!plainObject(value)||typeof value.id!=="string"||!value.id)return null;
  const questions=Array.isArray(value.questions)?value.questions.slice(0,QUESTION_COUNT).map((q,index)=>plainObject(q)?{id:safeText(q.id,80)||`q${index+1}`,question:safeText(q.question,1200),chinese:safeText(q.chinese,1200),competency:safeText(q.competency,200),jd_connection:safeText(q.jd_connection,1200)}:null):[];
  if(questions.length!==QUESTION_COUNT||questions.some(q=>!q?.question||!q?.chinese))return null;
  const attempts=Array.from({length:QUESTION_COUNT},(_,index)=>Array.isArray(value.attempts?.[index])?value.attempts[index].map(item=>{const feedback=cleanFeedback(item?.feedback);return feedback&&typeof item?.answer==="string"?{answer:safeText(item.answer,MAX_ANSWER),feedback}:null}).filter(Boolean).slice(0,6):[]);
  const current=Math.min(QUESTION_COUNT-1,Math.max(0,Number.isInteger(value.current)?value.current:0));
  const last=attempts[current].at(-1),allowed=new Set(["question","feedback","summary"]);
  let screen=allowed.has(value.screen)?value.screen:"question";
  if(screen==="feedback"&&!last)screen="question";
  if(screen==="summary"&&attempts.some(items=>!items.length))screen="question";
  const summary=plainObject(value.summary)&&plainObject(value.summary.avg)&&Array.isArray(value.summary.ranked)&&Array.isArray(value.summary.focus)&&Array.isArray(value.summary.review)?value.summary:null;
  return{id:value.id,createdAt:safeText(value.createdAt,80)||new Date().toISOString(),updatedAt:safeText(value.updatedAt,80)||new Date().toISOString(),company:safeText(value.company,MAX_COMPANY),position:safeText(value.position,MAX_POSITION),jd:safeText(value.jd,MAX_JD),questions,current,attempts,screen,feedback:screen==="feedback"?last?.feedback||null:null,retrying:Boolean(value.retrying&&last&&screen==="question"),draft:safeText(value.draft,MAX_ANSWER),completed:screen==="summary",summary};
}
function emptyStore(){return{version:STORAGE_VERSION,activeId:"",records:[]}}
function loadStore(){
  try{
    const raw=window.localStorage?.getItem(STORAGE_KEY);if(!raw)return emptyStore();
    const parsed=JSON.parse(raw);if(parsed?.version!==STORAGE_VERSION||!Array.isArray(parsed.records))return emptyStore();
    const records=parsed.records.map(cleanRecord).filter(Boolean).slice(0,MAX_HISTORY);
    return{version:STORAGE_VERSION,activeId:records.some(r=>r.id===parsed.activeId)?parsed.activeId:"",records};
  }catch{return emptyStore()}
}
store=loadStore();
function saveStore(){try{window.localStorage?.setItem(STORAGE_KEY,JSON.stringify(store))}catch{}}
function sessionRecord(){
  const now=new Date().toISOString();
  return{id:session.id,createdAt:session.createdAt||now,updatedAt:now,company:session.company,position:session.position,jd:session.jd,questions:session.questions,current:session.current,attempts:session.attempts,screen:session.screen,feedback:session.feedback,retrying:session.retrying,draft:session.draft,completed:session.screen==="summary",summary:session.summary};
}
function persist(){
  if(!session.id||session.questions.length!==QUESTION_COUNT)return;
  const record=sessionRecord(),existing=store.records.filter(item=>item.id!==session.id);
  store={version:STORAGE_VERSION,activeId:session.id,records:[record,...existing].slice(0,MAX_HISTORY)};saveStore();
}
function applyRecord(record){const clean=cleanRecord(record);if(!clean)return false;Object.assign(session,freshSession(),clean,{busy:false,error:""});return true}
function recordMeta(record){
  const answered=record.attempts.filter(items=>items.length).length,date=new Date(record.createdAt),latest=record.attempts.map(items=>items.at(-1)?.feedback).filter(Boolean);
  const average=latest.length?Math.round(latest.reduce((sum,item)=>sum+item.total_score,0)/latest.length):0;
  return{answered,date:Number.isNaN(date.getTime())?"日期未知":date.toLocaleDateString("zh-CN"),result:record.completed?`平均 ${average} / 30`:`${answered} / ${QUESTION_COUNT} 已回答`};
}
function savedSessionsView(){
  if(!store.records.length)return"";
  const active=store.records.find(item=>item.id===store.activeId),resume=active?(()=>{const meta=recordMeta(active);return `<section class="mock-resume panel"><div><span class="saved-kicker">继续上次模拟</span><h2>${esc(active.position)}</h2><p>${esc(active.company||"未填写公司")} · ${meta.result}</p></div><button class="button" data-resume-id="${esc(active.id)}">${active.completed?"查看结果":"继续"}</button></section>`})():"";
  const history=`<section class="mock-history"><div class="saved-heading"><div><span class="saved-kicker">最近 5 次</span><h2>历史模拟</h2></div><span>${store.records.length} 条</span></div><div class="history-list">${store.records.map(record=>{const meta=recordMeta(record);return `<article class="history-item panel"><button class="history-open" data-resume-id="${esc(record.id)}"><strong>${esc(record.position)}</strong><span>${esc(record.company||"未填写公司")} · ${meta.date}</span><small>${record.completed?"已完成":"进行中"} · ${meta.result}${record.id===store.activeId?" · 当前":""}</small></button><button class="history-delete" data-delete-id="${esc(record.id)}" aria-label="删除 ${esc(record.position)} 的模拟记录">删除</button></article>`}).join("")}</div></section>`;
  return resume+history;
}

function setupView(){return `<div class="mock-wrap"><section class="hero mock-hero"><div class="eyebrow">V0.3 · TEXT MOCK INTERVIEW</div><h1>针对岗位，练一场文字面试</h1><p class="lead">粘贴岗位描述，生成 5 道相关问题。每次回答后获得结构化诊断，并可立即重答。</p></section>${savedSessionsView()}<form class="mock-form panel" id="mockSetup"><div class="saved-heading form-heading"><div><span class="saved-kicker">NEW SESSION</span><h2>开始新的模拟</h2></div></div><label class="field"><span>Company <small>公司 · 可选</small></span><input id="mockCompany" maxlength="${MAX_COMPANY}" autocomplete="organization" value="${esc(session.company)}" placeholder="例如：某科技公司"></label><label class="field"><span>Position <small>岗位 · 必填</small></span><input id="mockPosition" maxlength="${MAX_POSITION}" required value="${esc(session.position)}" placeholder="例如：Product Operations Intern"></label><label class="field"><span>Job Description <small>JD · 必填</small></span><textarea id="mockJd" maxlength="${MAX_JD}" required rows="10" placeholder="粘贴完整岗位描述…">${esc(session.jd)}</textarea><span class="field-count"><span id="jdCount">${session.jd.length}</span> / ${MAX_JD}</span></label><div class="fixed-count"><span>Question Count</span><strong>5 题</strong></div><p class="privacy-note">隐私提示：你的岗位信息和回答将发送至 AI 服务用于生成面试问题与反馈；模拟记录仅保存在当前浏览器，可在“历史模拟”中删除。本版本不收集姓名，也不会在服务器永久存储完整回答。</p>${session.error?`<div class="inline-error" role="alert">${esc(session.error)}</div>`:""}<button class="button full" type="submit" ${session.busy?"disabled":""}>${session.busy?'<span class="spinner" aria-hidden="true"></span> 正在生成岗位问题…':"Start Mock Interview"}</button></form></div>`}

function progress(){return `<div class="mock-progress" aria-label="面试进度"><div class="mock-progress-head"><span>Question ${session.current+1} / ${QUESTION_COUNT}</span><button id="mockSessions" type="button">模拟记录 / 新模拟</button></div><div><i style="width:${((session.current+1)/QUESTION_COUNT)*100}%"></i></div></div>`}
function questionView(){const q=session.questions[session.current];if(!q)return setupView();const previous=session.attempts[session.current]?.at(-1),value=session.retrying?(session.draft||previous?.answer||""):session.draft;return `<div class="mock-wrap">${progress()}<article class="mock-question panel"><div class="competency">${esc(q.competency||"Role fit")}</div><h1>${esc(q.question)}</h1><p class="question-zh">${esc(q.chinese)}</p>${session.retrying?`<div class="retry-banner"><strong>Try Again</strong><span>重点改进：${esc((previous?.feedback?.retry_focus||[]).join("；"))}</span></div>`:""}<form id="mockAnswerForm"><label class="field answer-field"><span>Your Answer <small>请用英文回答</small></span><textarea id="mockAnswer" maxlength="${MAX_ANSWER}" rows="11" required placeholder="Type your answer in English…">${esc(value)}</textarea><span class="field-count"><span id="answerCount">${value.length}</span> / ${MAX_ANSWER}</span></label>${session.error?`<div class="inline-error" role="alert">${esc(session.error)}</div>`:""}<button class="button full" type="submit" ${session.busy?"disabled":""}>${session.busy?'<span class="spinner" aria-hidden="true"></span> 正在分析回答…':"Submit Answer"}</button></form></article></div>`}

function languageFixes(items){if(!items?.length)return `<p class="muted-copy">没有需要优先修改的明显语言问题。</p>`;return `<div class="language-fixes">${items.map(x=>`<div><del>${esc(x.original)}</del><strong>${esc(x.improved)}</strong><p>${esc(x.reason)}</p></div>`).join("")}</div>`}
function feedbackView(){const f=session.feedback,q=session.questions[session.current],attempt=session.attempts[session.current]?.at(-1),retry=session.attempts[session.current]?.length>1;return `<div class="mock-wrap">${progress()}<article class="feedback-head panel"><div><div class="eyebrow">回答诊断 · ANSWER DIAGNOSIS</div><h1>${f.total_score}<span> / 30</span></h1></div><p>${esc(f.overall_diagnosis)}</p></article><section class="score-grid" aria-label="六维评分">${Object.entries(labels).map(([key,label])=>`<div class="score-item ${scoreClass(f[key])}"><span>${label}</span><strong>${f[key]} / 5</strong></div>`).join("")}</section>${retry?`<section class="comparison-grid"><article class="feedback-section improved"><h2>本次进步 Improved</h2>${list(f.improved)}</article><article class="feedback-section missing"><h2>仍需补充 Still Missing</h2>${list(f.still_missing)}</article></section>`:""}<section class="feedback-stack"><article class="feedback-section"><h2>做得好的地方 Strengths</h2>${list(f.strengths)}</article><article class="feedback-section priority"><h2>最大问题 Biggest Weakness</h2><p>${esc(f.biggest_weakness)}</p></article><article class="feedback-section"><h2>如何改进 How to Improve</h2>${list(f.improvement_advice)}</article><article class="feedback-section"><h2>语言修正 Language Fixes</h2>${languageFixes(f.language_fixes)}</article><article class="feedback-section"><h2>更好的结构 Better Structure</h2>${list(f.better_structure,"structure-list")}</article><article class="feedback-section suggested"><h2>参考回答 Suggested Answer</h2><p lang="en">${esc(f.suggested_answer)}</p>${f.suggested_answer_rationale?`<div class="answer-rationale"><strong>回答思路</strong><span>${esc(f.suggested_answer_rationale)}</span></div>`:""}<small>参考回答只重组你已提供的信息；缺少的经历或结果会保留为待补充内容。</small></article><article class="feedback-section focus"><h2>重答重点 Retry Focus</h2>${list(f.retry_focus)}</article></section><div class="mock-actions"><button class="button secondary" id="mockRetry">Try Again</button><button class="button" id="mockNext">${session.current===QUESTION_COUNT-1?"View Summary":"Next Question"}</button></div><details class="question-context"><summary>查看本题与回答</summary><p>${esc(q.question)}</p><blockquote lang="en">${esc(attempt?.answer)}</blockquote></details></div>`}

function summaryData(){const latest=session.attempts.map(a=>a.at(-1)?.feedback).filter(Boolean),keys=Object.keys(labels),avg={};keys.forEach(k=>avg[k]=latest.length?Math.round(latest.reduce((s,f)=>s+f[k],0)/latest.length*10)/10:0);const ranked=[...keys].sort((a,b)=>avg[b]-avg[a]),focus=[...new Set(latest.flatMap(f=>f.retry_focus||[]))].slice(0,3),reviewMap={relevance_score:"岗位匹配与求职动机",structure_score:"回答结构与听觉路标",evidence_score:"项目经历与具体证据",action_result_score:"个人行动、结果与岗位回扣",clarity_score:"一句一个主要观点",english_score:"易错表达与口语练习"},overall=avg[ranked[0]]>=4?"整体回答已经具备较好的面试信息密度。":"你已经完成了完整输出；下一步应集中修复最影响说服力的短板。";return{latest,avg,ranked,focus,review:[reviewMap[ranked.at(-1)],reviewMap[ranked.at(-2)]].filter(Boolean),overall}}
function summaryView(){const s=session.summary||summaryData(),strong=labels[s.ranked[0]],weak=labels[s.ranked.at(-1)];return `<div class="mock-wrap"><section class="summary-hero panel"><div class="eyebrow">5 / 5 COMPLETE</div><h1>本轮模拟面试完成</h1><p>${esc(s.overall)}</p></section><section class="summary-key"><article><span>最强项 Strongest Area</span><strong>${esc(strong)}</strong></article><article><span>最大短板 Biggest Weakness</span><strong>${esc(weak)}</strong></article></section><section class="feedback-section"><h2>六维平均表现</h2><div class="average-list">${Object.entries(labels).map(([k,l])=>`<div><span>${l}</span><div><i style="width:${s.avg[k]*20}%"></i></div><strong>${s.avg[k]}</strong></div>`).join("")}</div></section><section class="feedback-section priority"><h2>下一步直接练这些</h2>${list(s.focus.length?s.focus:[`为“${weak}”补充更具体的信息`])}</section><section class="feedback-section"><h2>建议回到 EIT 复习</h2>${list(s.review)}</section><div class="mock-actions"><button class="button secondary" id="mockHome">回到首页</button><button class="button" id="mockRestart">再练一场</button></div></div>`}

function render(){return session.screen==="question"?questionView():session.screen==="feedback"?feedbackView():session.screen==="summary"?summaryView():setupView()}
function paint(){document.querySelector("#view").innerHTML=render();bind(helpers);document.querySelector("#view").focus({preventScroll:true});scrollTo({top:0,behavior:"smooth"})}
function friendlyError(error){const code=error?.code||"";if(code==="TIMEOUT")return"AI 分析等待时间过长，请稍后重试。你的当前回答仍保留在页面上。";if(code==="INSUFFICIENT_BALANCE")return"AI 服务余额不足，暂时无法生成反馈。请联系维护者处理后再试。";if(code==="RATE_LIMITED")return"请求有些频繁，请稍等一分钟后再试。";if(code==="NOT_CONFIGURED")return"模拟面试服务尚未完成配置，学习模块仍可正常使用。";if(code==="INVALID_RESPONSE")return"AI 返回的反馈格式不完整，请重新提交一次。";if(code==="NETWORK_ERROR")return"网络连接失败，请检查网络后重试。";return error?.message&&error.safe?error.message:"AI 服务暂时不可用，请稍后重试。"}
async function api(action,payload){if(!endpoint()){const e=new Error("not configured");e.code="NOT_CONFIGURED";throw e}const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),32000);let response;try{response=await fetch(endpoint(),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,...payload}),signal:controller.signal})}catch(error){const e=new Error("network");e.code=error?.name==="AbortError"?"TIMEOUT":"NETWORK_ERROR";throw e}finally{clearTimeout(timer)}let body={};try{body=await response.json()}catch{const e=new Error("invalid response");e.code="INVALID_RESPONSE";throw e}if(!response.ok||!body.ok){const e=new Error(body.message||"request failed");e.code=body.code||"API_ERROR";e.safe=true;throw e}return body.data}

async function start(){session.company=document.querySelector("#mockCompany").value.trim();session.position=document.querySelector("#mockPosition").value.trim();session.jd=document.querySelector("#mockJd").value.trim();if(!session.position||!session.jd){session.error="请填写岗位和 Job Description。";paint();return}session.busy=true;session.error="";paint();try{const data=await api("generate",{company:session.company,position:session.position,jd:session.jd});Object.assign(session,{id:`mock-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,createdAt:new Date().toISOString(),questions:data.questions,attempts:Array.from({length:QUESTION_COUNT},()=>[]),current:0,screen:"question",completed:false,summary:null,retrying:false,draft:""});persist()}catch(e){session.error=friendlyError(e)}finally{session.busy=false;paint()}}
async function submitAnswer(){const answer=document.querySelector("#mockAnswer").value.trim();if(!answer){session.error="请先输入英文回答。";paint();return}const history=session.attempts[session.current],previous=history.at(-1);session.draft=answer;persist();session.busy=true;session.error="";paint();try{const feedback=await api("evaluate",{company:session.company,position:session.position,jd:session.jd,question:session.questions[session.current],answer,previous_answer:session.retrying?previous?.answer:"",previous_feedback:session.retrying?previous?.feedback:null});history.push({answer,feedback});session.feedback=feedback;session.draft="";session.screen="feedback";persist()}catch(e){session.error=friendlyError(e);session.screen="question";persist()}finally{session.busy=false;paint()}}
function newSession(){store.activeId="";saveStore();Object.assign(session,freshSession());paint()}
function resumeRecord(id){const record=store.records.find(item=>item.id===id);if(!record||!applyRecord(record))return;store.activeId=id;saveStore();paint()}
function deleteRecord(id){store.records=store.records.filter(item=>item.id!==id);if(store.activeId===id){store.activeId="";Object.assign(session,freshSession())}saveStore();paint()}
function bind(ctx=helpers){helpers=ctx;const setup=document.querySelector("#mockSetup");if(setup)setup.onsubmit=e=>{e.preventDefault();start()};const jd=document.querySelector("#mockJd");if(jd)jd.oninput=e=>document.querySelector("#jdCount").textContent=e.target.value.length;document.querySelectorAll("[data-resume-id]").forEach(button=>button.onclick=()=>resumeRecord(button.dataset.resumeId));document.querySelectorAll("[data-delete-id]").forEach(button=>button.onclick=()=>{if(window.confirm("删除这次模拟记录？此操作无法撤销。"))deleteRecord(button.dataset.deleteId)});const sessions=document.querySelector("#mockSessions");if(sessions)sessions.onclick=newSession;const answerForm=document.querySelector("#mockAnswerForm");if(answerForm)answerForm.onsubmit=e=>{e.preventDefault();submitAnswer()};const answer=document.querySelector("#mockAnswer");if(answer)answer.oninput=e=>{session.draft=e.target.value;document.querySelector("#answerCount").textContent=e.target.value.length;persist()};const retry=document.querySelector("#mockRetry");if(retry)retry.onclick=()=>{session.retrying=true;session.screen="question";session.error="";session.draft="";persist();paint();setTimeout(()=>document.querySelector("#mockAnswer")?.focus(),0)};const next=document.querySelector("#mockNext");if(next)next.onclick=()=>{session.retrying=false;session.draft="";session.error="";if(session.current>=QUESTION_COUNT-1){session.screen="summary";session.summary=summaryData()}else{session.current++;session.screen="question"}persist();paint()};const home=document.querySelector("#mockHome");if(home)home.onclick=()=>ctx.navigate("home");const restart=document.querySelector("#mockRestart");if(restart)restart.onclick=newSession}

window.MockInterview={render,bind,reset:newSession,_session:session,_summaryData:summaryData,_friendlyError:friendlyError,_storageKey:STORAGE_KEY,_loadStore:loadStore,_persist:persist,_applyRecord:applyRecord};
})();
